    const line = lines[i]
    const fence = getFence(line)

    if (!inCodeBlock && fence) {
      const hasLanguageInfo = fence.info && fence.info.trim()

      if (hasLanguageInfo) {
        // CHANGED: Check if this is a diagram language inside markdown context
        // If so, treat it as content, not a block separator
        if (isMarkdownBlockType(currentType) && isDiagramLanguage(fence.info)) {
          currentContent.push(line)
          continue
        }

        // Mark previous block finished when a new fence opens
        if (blocks.length > 0) {
          blocks[blocks.length - 1].finished = true
        }

        // pass isFinished=true for completed prior block
        if (currentContent.length) addBlock(true)

        const parts = fence.info.split(/\s+/).filter(Boolean)
        inCodeBlock = true
        currentFence = fence
        currentType = parts[0] || 'text'
        currentFileName = parts[1] || ''
        isAnonymousFence = false
        continue
      } else {
        // Anonymous fence (no language) - treat as markdown content
        if (!inCodeBlock) {
          currentContent.push(line)
          continue
        }
      }
    }

    if (!inCodeBlock) {
      currentContent.push(line)
      continue
    }

    // CHANGED: For named blocks, only close on an exact match (same char, no info)
    // Inner fences with info or different chars are just content
    if (currentFileName || !isAnonymousFence) {
      // Named block or regular code block - strict closing
      if (isClosingFence(line, currentFence)) {
        // This closes the block
        addBlock(true)
        inCodeBlock = false
        continue
      }
      // Any other fence (with or without info) is content
      currentContent.push(line)
      continue
    }

    // Anonymous fence handling (original logic for compatibility)
    const allNestedClosed = true // Simplified since we're not tracking nested for anonymous
    if (allNestedClosed && isClosingFence(line, currentFence)) {
      if (isNestedAnonymousFence(lines, i, currentType, currentFence)) {
        currentContent.push(line)
        continue
      }
      // closing fence found — block is finished
      addBlock(true)
      inCodeBlock = false
      continue
    }

    currentContent.push(line)
