    resetBlock()
  }

  function resetBlock() {
    currentType = 'markdown'
    currentContent = []
    currentFileName = ''
    currentFence = null
    isAnonymousFence = false
  }

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i]
    const fence = getFence(line)

    // CHANGED: If we're in a markdown block, all inner fences are content
    if (inCodeBlock && isMarkdownBlockType(currentType) && fence) {
      currentContent.push(line)
      continue
    }

    if (!inCodeBlock && fence) {
      const hasLanguageInfo = fence.info && fence.info.trim()

