      addBlock(true)
      inCodeBlock = false
      continue
    }

    currentContent.push(line)
  }

  if (currentContent.length) {
    addBlock(false)
  }

  // All blocks except the last are finished
  for (let i = 0; i < blocks.length - 1; i++) {
    blocks[i].finished = true
  }

  return blocks
}

