        if (blocks.length > 0) {
          blocks[blocks.length - 1].finished = true
        }

        if (currentContent.length) addBlock(true)

        const parts = fence.info.split(/\s+/).filter(Boolean)
        inCodeBlock = true
        currentFence = fence
        currentType = parts[0] || 'text'
        currentFileName = parts[1] || ''
        isAnonymousFence = false
        continue
      } else {
        // Anonymous fence (no language) - treat as markdown content
        if (!inCodeBlock) {
          currentContent.push(line)
          continue
        }
      }
    }

    if (!inCodeBlock) {
      currentContent.push(line)
      continue
    }

    // In a code block - check for closing fence
    if (currentFileName || !isAnonymousFence) {
      // Named block or regular code block - strict closing
      if (isClosingFence(line, currentFence)) {
        addBlock(true)
        inCodeBlock = false
        continue
      }
      currentContent.push(line)
      continue
    }

    // Anonymous fence handling
    const allNestedClosed = true
    if (allNestedClosed && isClosingFence(line, currentFence)) {
      if (isNestedAnonymousFence(lines, i, currentType, currentFence)) {
        currentContent.push(line)
        continue
      }
      addBlock(true)
      inCodeBlock = false
      continue
    }

    currentContent.push(line)
  }

  if (currentContent.length) {
    addBlock(false)
  }

  // All blocks except the last are finished
  for (let i = 0; i < blocks.length - 1; i++) {
    blocks[i].finished = true
  }

